fields.InputDefinition:
{
  "goal": "In the MoreCheese app, open 'Competition Entries' from the app's navigation (if it is not there, type 'Competition Entries' in the LEFT sidebar 'Search record types...' box and click that match, or navigate to http://localhost:4200/app/data-explorer/Data?entity=MoreCheese:%20Competition%20Entries). The grid lists competition entries. Type 'Old Alderwick' in the grid's filter box ('Filter records...') so that only Old Alderwick entries show. Open the entry with Entry Key ICF-000107:2019:1 (Henri Dubois, 2019): click its row and then 'Open Full Record', or double-click the row. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200/app/morecheese",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
